from typing import List, Optional


class Node:
    def __init__(self, value: int) -> None:
        self.data = value
        self.next: Optional["Node"] = None
        self.prev: Optional["Node"] = None


class Solution:
    # Find all pairs with target sum using two pointers.
    def findPairsWithGivenSum(self, head: Optional[Node], target: int) -> List[List[int]]:
        answer: List[List[int]] = []
        if head is None:
            return answer

        left = head
        right = head

        # Move right pointer to final node.
        while right.next is not None:
            right = right.next

        # Move pointers inward until meeting or crossing.
        while left != right and right.next != left:
            current_sum = left.data + right.data

            if current_sum == target:
                answer.append([left.data, right.data])
                left = left.next
                right = right.prev
            elif current_sum < target:
                left = left.next
            else:
                right = right.prev

        return answer


# Build a doubly linked list from array values.
def build_list(values: List[int]) -> Optional[Node]:
    if not values:
        return None

    head = Node(values[0])
    tail = head

    for value in values[1:]:
        node = Node(value)
        tail.next = node
        node.prev = tail
        tail = node

    return head


